int check_missing_lock(SourceFile*f,Project*p,Issue*out){int cnt=0;int has_mutex=0;int has_lock=0;int has_unlock=0;for(int i=0;i<f->ntokens;i++){if(f->tokens[i].type==TK_ID){if(strcmp(f->tokens[i].text,"pthread_mutex_t")==0||strcmp(f->tokens[i].text,"mutex")==0||strcmp(f->tokens[i].text,"pthread_mutex_lock")==0)has_mutex=1;if(strcmp(f->tokens[i].text,"pthread_mutex_lock")==0||strcmp(f->tokens[i].text,"lock")==0||strcmp(f->tokens[i].text,"mtx_lock")==0)has_lock=1;if(strcmp(f->tokens[i].text,"pthread_mutex_unlock")==0||strcmp(f->tokens[i].text,"unlock")==0||strcmp(f->tokens[i].text,"mtx_unlock")==0)has_unlock=1;}}if(has_mutex&&!has_lock){cnt++;if(cnt==1&&out){out->sev=SEV_WARNING;out->cat=CAT_CONCURRENCY;out->code=6001;snprintf(out->msg,sizeof(out->msg),"Mutex declared but lock() never called");}}if(has_lock&&!has_unlock&&has_mutex){cnt++;if(cnt==1&&out){out->sev=SEV_WARNING;out->cat=CAT_CONCURRENCY;out->code=6001;snprintf(out->msg,sizeof(out->msg),"Mutex locked but unlock() may not be called");}}return cnt;}
int check_double_lock(SourceFile*f,Project*p,Issue*out){int cnt=0;for(int i=0;i<f->ntokens-3;i++){if((f->tokens[i].type==TK_ID&&strcmp(f->tokens[i].text,"lock")==0)||(f->tokens[i].type==TK_ID&&strcmp(f->tokens[i].text,"pthread_mutex_lock")==0)){char*mutex_name=f->tokens[i+2].type==TK_ID?f->tokens[i+2].text:"";for(int j=i+1;j<f->ntokens-2&&j<i+50;j++){if((f->tokens[j].type==TK_ID&&strcmp(f->tokens[j].text,"lock")==0)||(f->tokens[j].type==TK_ID&&strcmp(f->tokens[j].text,"pthread_mutex_lock")==0)){char*m2=f->tokens[j+2].type==TK_ID?f->tokens[j+2].text:"";if(strcmp(mutex_name,m2)==0&&mutex_name[0]){cnt++;if(cnt==1&&out){LOC_TOK(out,f,j);out->sev=SEV_ERROR;out->cat=CAT_CONCURRENCY;out->code=6002;snprintf(out->msg,sizeof(out->msg),"Double lock on mutex '%s'",mutex_name);snprintf(out->suggestion,sizeof(out->suggestion),"Use recursive mutex or restructure to avoid double lock");}break;}}}}}return cnt;}
int check_unlock_path(SourceFile*f,Project*p,Issue*out){int cnt=0;for(int i=0;i<f->ntokens-2;i++){if(f->tokens[i].type==TK_ID&&(strcmp(f->tokens[i].text,"lock")==0||strcmp(f->tokens[i].text,"pthread_mutex_lock")==0)){int lock_line=f->tokens[i].line;int has_unlock=0;for(int j=i+1;j<f->ntokens&&j<i+200;j++){if(f->tokens[j].type==TK_RBRACE||f->tokens[j].type==TK_BLOCK_CLOSE){break;}if(f->tokens[j].type==TK_ID&&(strcmp(f->tokens[j].text,"unlock")==0||strcmp(f->tokens[j].text,"pthread_mutex_unlock")==0)){has_unlock=1;break;}if(f->tokens[j].type==TK_RETURN&&!has_unlock){cnt++;if(cnt==1&&out){LOC_TOK(out,f,i);out->sev=SEV_ERROR;out->cat=CAT_CONCURRENCY;out->code=6003;snprintf(out->msg,sizeof(out->msg),"Return without unlocking mutex at line %d",lock_line);snprintf(out->suggestion,sizeof(out->suggestion),"Ensure unlock is called before all return paths");}}}if(!has_unlock){}}}return cnt;}
int check_lock_order(SourceFile*f,Project*p,Issue*out){int cnt=0;char*locks[64];int nlocks=0;for(int i=0;i<f->ntokens-2;i++){if(f->tokens[i].type==TK_ID&&(strcmp(f->tokens[i].text,"lock")==0||strcmp(f->tokens[i].text,"pthread_mutex_lock")==0)){if(f->tokens[i+2].type==TK_ID&&nlocks<64){locks[nlocks++]=f->tokens[i+2].text;}}}for(int i=1;i<nlocks;i++){for(int j=0;j<i;j++){if(strcmp(locks[i],locks[j])==0){cnt++;if(cnt==1&&out){out->sev=SEV_WARNING;out->cat=CAT_CONCURRENCY;out->code=6004;snprintf(out->msg,sizeof(out->msg),"Possible lock ordering violation");snprintf(out->suggestion,sizeof(out->suggestion),"Establish a consistent lock ordering to prevent deadlocks");}break;}}}return cnt;}
int check_thread_unsafe(SourceFile*f,Project*p,Issue*out){int cnt=0;const char*unsafe_funcs[]={"strtok","asctime","ctime","gmtime","localtime","rand","strerror","tmpnam","gethostbyname","gethostbyaddr",NULL};for(int i=0;i<f->ntokens;i++){if(f->tokens[i].type==TK_ID){for(int s=0;unsafe_funcs[s];s++){if(strcmp(f->tokens[i].text,unsafe_funcs[s])==0){cnt++;if(cnt==1&&out){LOC_TOK(out,f,i);out->sev=SEV_WARNING;out->cat=CAT_CONCURRENCY;out->code=6005;snprintf(out->msg,sizeof(out->msg),"Thread-unsafe function '%s' used",unsafe_funcs[s]);snprintf(out->suggestion,sizeof(out->suggestion),"Use the _r variant (reentrant version) for multithreaded code");}break;}}}}return cnt;}
int check_global_data_race(SourceFile*f,Project*p,Issue*out){int cnt=0;int global_vars=0;int threads=0;int locks=0;for(int i=0;i<f->ntokens;i++){if(f->tokens[i].type==TK_ID){if(strcmp(f->tokens[i].text,"pthread_create")==0)threads++;if(strcmp(f->tokens[i].text,"pthread_mutex_lock")==0||strcmp(f->tokens[i].text,"lock")==0)locks++;}}for(int i=0;i<f->ntokens-2;i++){if(f->tokens[i].type==TK_INT&&f->tokens[i+1].type==TK_ID&&f->tokens[i+2].type==TK_SEMI){global_vars++;}}if(threads>0&&global_vars>0&&locks==0){cnt++;if(cnt==1&&out){out->sev=SEV_ERROR;out->cat=CAT_CONCURRENCY;out->code=6006;snprintf(out->msg,sizeof(out->msg),"Threads created with %d global variables but no locks found",global_vars);snprintf(out->suggestion,sizeof(out->suggestion),"Add mutex protection to shared global variables");}}return cnt;}
int check_signal_mt(SourceFile*f,Project*p,Issue*out){int cnt=0;int has_signal=0;int has_thread=0;for(int i=0;i<f->ntokens;i++){if(f->tokens[i].type==TK_ID&&strcmp(f->tokens[i].text,"signal")==0)has_signal=1;if(f->tokens[i].type==TK_ID&&strcmp(f->tokens[i].text,"pthread_create")==0)has_thread=1;}if(has_signal&&has_thread){cnt++;if(cnt==1&&out){out->sev=SEV_WARNING;out->cat=CAT_CONCURRENCY;out->code=6007;snprintf(out->msg,sizeof(out->msg),"Signals used in multithreaded program - signal handler runs unpredictably");snprintf(out->suggestion,sizeof(out->suggestion),"Avoid signals in multithreaded code, use condition variables instead");}}return cnt;}
int check_tls_usage(SourceFile*f,Project*p,Issue*out){int cnt=0;for(int i=0;i<f->ntokens;i++){if(f->tokens[i].type==TK_ID&&(strcmp(f->tokens[i].text,"__thread")==0||strcmp(f->tokens[i].text,"_Thread_local")==0||strcmp(f->tokens[i].text,"thread_local")==0)){cnt++;if(cnt==1&&out){LOC_TOK(out,f,i);out->sev=SEV_INFO;out->cat=CAT_CONCURRENCY;out->code=6008;snprintf(out->msg,sizeof(out->msg),"Thread-local storage detected");snprintf(out->suggestion,sizeof(out->suggestion),"Ensure TLS access is efficient and not overused");}}}return cnt;}
int check_condition_var(SourceFile*f,Project*p,Issue*out){int cnt=0;int has_cond=0;int has_wait=0;int has_signal_cv=0;for(int i=0;i<f->ntokens;i++){if(f->tokens[i].type==TK_ID){if(strcmp(f->tokens[i].text,"pthread_cond_t")==0)has_cond=1;if(strcmp(f->tokens[i].text,"pthread_cond_wait")==0)has_wait=1;if(strcmp(f->tokens[i].text,"pthread_cond_signal")==0||strcmp(f->tokens[i].text,"pthread_cond_broadcast")==0)has_signal_cv=1;}}if(has_cond&&(!has_wait||!has_signal_cv)){cnt++;if(cnt==1&&out){out->sev=SEV_WARNING;out->cat=CAT_CONCURRENCY;out->code=6009;snprintf(out->msg,sizeof(out->msg),"Condition variable declared but missing wait or signal");}}return cnt;}
int check_barrier_usage(SourceFile*f,Project*p,Issue*out){int cnt=0;for(int i=0;i<f->ntokens;i++){if(f->tokens[i].type==TK_ID&&strstr(f->tokens[i].text,"barrier")!=NULL){cnt++;}}if(cnt>0&&cnt==1&&out){out->sev=SEV_INFO;out->cat=CAT_CONCURRENCY;out->code=6010;snprintf(out->msg,sizeof(out->msg),"Barrier usage detected - check for correctness");}return cnt>0?1:0;}
